protected int findWrapPos(String text, int width, int startPos) {
    Objects.requireNonNull(text, "text cannot be null");

    if (width <= 0) {
        throw new IllegalArgumentException("width must be positive");
    }
    if (startPos < 0 || startPos > text.length()) {
        throw new IndexOutOfBoundsException("startPos: " + startPos + " out of bounds for text length " + text.length());
    }

    // If no text remains to wrap, or the remaining text is shorter than the width,
    // it means the rest of the text fits on the current line.
    if (startPos >= text.length() || startPos + width >= text.length()) {
        return -1;
    }

    // Calculate the effective end position for the current line segment
    int maxWrapPos = startPos + width;

    // 1. Check for explicit line breaks or tabs within the allowed width
    int newlinePos = text.indexOf('\n', startPos);
    int tabPos = text.indexOf('\t', startPos);

    int explicitBreakPos = -1;

    if (newlinePos != -1 && newlinePos < maxWrapPos) {
        explicitBreakPos = newlinePos;
    }
    if (tabPos != -1 && tabPos < maxWrapPos) {
        if (explicitBreakPos == -1 || tabPos < explicitBreakPos) {
            explicitBreakPos = tabPos;
        }
    }

    if (explicitBreakPos != -1) {
        // Return the position *after* the explicit break character
        return explicitBreakPos + 1;
    }

    // 2. Look for the last whitespace character before maxWrapPos
    // Start searching from maxWrapPos, moving backwards
    int pos = maxWrapPos;
    char c;

    // Iterate backwards from maxWrapPos down to startPos
    // Stop if a whitespace character (' ', '\n', '\r', '\t') is found
    while (pos >= startPos) {
        c = text.charAt(pos - 1); // Check character *before* current 'pos'
        if (Character.isWhitespace(c)) { // Use Character.isWhitespace for broader Unicode support
            // Found a whitespace. This is a potential wrap point.
            // We want to break *before* this whitespace, so return its index.
            return pos - 1;
        }
        --pos;
    }

    // 3. If no whitespace was found before maxWrapPos,
    // then we must chop the word. Find the first whitespace or end of string
    // *after* maxWrapPos.
    pos = maxWrapPos;
    while (pos < text.length()) {
        c = text.charAt(pos);
        if (Character.isWhitespace(c)) {
            // Found a whitespace, break at this position.
            return pos;
        }
        ++pos;
    }

    // If we reach here, it means the entire remaining segment from startPos
    // to text.length() is a single word (or contains no suitable break points)
    // and it extends beyond 'width'.
    // In this case, we return -1, indicating the rest of the text fits
    // (as it's a single unbreakable unit that we've decided to let extend).
    // This aligns with the initial check for `startPos + width >= text.length()`.
    return -1;
}
