public static String join(Object[] array, char separator, int startIndex, int endIndex) {
    if (array == null) {
        return null;
    }

    // Validate indices
    if (startIndex < 0 || startIndex > array.length) {
        throw new IndexOutOfBoundsException("startIndex: " + startIndex + ", array length: " + array.length);
    }
    if (endIndex < 0 || endIndex > array.length) {
        throw new IndexOutOfBoundsException("endIndex: " + endIndex + ", array length: " + array.length);
    }
    if (startIndex > endIndex) {
        return EMPTY; // Or throw IllegalArgumentException, depending on desired contract
    }

    int noOfItems = (endIndex - startIndex);
    if (noOfItems <= 0) {
        return EMPTY;
    }

    // Calculate a more accurate initial capacity for StringBuilder
    // Sum of lengths of all elements + (number of separators * 1)
    int estimatedLength = 0;
    for (int i = startIndex; i < endIndex; i++) {
        if (array[i] != null) {
            estimatedLength += array[i].toString().length();
        }
    }
    // Add space for separators (noOfItems - 1 separators if noOfItems > 0)
    if (noOfItems > 1) {
        estimatedLength += (noOfItems - 1);
    }

    StringBuilder buf = new StringBuilder(estimatedLength);

    for (int i = startIndex; i < endIndex; i++) {
        if (i > startIndex) {
            buf.append(separator);
        }
        if (array[i] != null) {
            buf.append(array[i]);
        }
    }
    return buf.toString();
}
