                    // Signal EOF to the Base64 codec to flush any remaining buffered data.
                    if (doEncode) {
                        base64.encode(buf, 0, -1); // Pass -1 to signal EOF for encoding
                    } else {
                        base64.decode(buf, 0, -1); // Pass -1 to signal EOF for decoding
                    }
                } else if (c > 0) { // Data read successfully
                    if (doEncode) {
                        base64.encode(buf, 0, c);
                    } else {
                        base64.decode(buf, 0, c);
                    }
