            // For simplicity and to avoid large temporary arrays, we'll generate directly from the range.
            charSource = null; // Indicate direct generation from start/end
            charSourceStart = start;
            charSourceEnd = end;
        }

        StringBuilder buffer = new StringBuilder(count);
        int currentCount = 0;

        while (currentCount < count) {
            int codePoint;

            if (charSource != null) {
                // Pick a character from the provided array
                codePoint = charSource[random.nextInt(charSourceEnd - charSourceStart) + charSourceStart];
            } else {
                // Pick a character from the defined Unicode range
                codePoint = random.nextInt(charSourceEnd - charSourceStart) + charSourceStart;
            }

            // Filter based on letters/numbers flags
            if ((letters && !Character.isLetter(codePoint)) || (numbers && !Character.isDigit(codePoint))) {
                // If filtering is active and character doesn't match, retry
                continue;
            }

            // Handle surrogate pairs
            if (Character.isSurrogate((char) codePoint)) {
                if (Character.isHighSurrogate((char) codePoint)) {
                    // High surrogate generated, need to append a low surrogate
                    if (currentCount + 1 >= count) {
                        // Not enough space for a pair, skip this high surrogate
                        continue;
                    }
                    buffer.append((char) codePoint);
                    buffer.append((char) (0xDC00 + random.nextInt(0x400))); // Random low surrogate
                    currentCount += 2;
                } else if (Character.isLowSurrogate((char) codePoint)) {
                    // Low surrogate generated, need to prepend a high surrogate
                    if (currentCount + 1 >= count) {
                        // Not enough space for a pair, skip this low surrogate
                        continue;
                    }
                    buffer.append((char) (0xD800 + random.nextInt(0x400))); // Random high surrogate
                    buffer.append((char) codePoint);
                    currentCount += 2;
                }
            } else {
                // Regular character or non-BMP character (handled by appendCodePoint)
                buffer.appendCodePoint(codePoint);
                currentCount++;
            }
        }
        return buffer.toString();
    }
