public static String join(Object[] array, String separator, int startIndex, int endIndex) {
    if (array == null) {
        return null;
    }
    if (separator == null) {
        separator = EMPTY;
    }

    // Validate indices to prevent ArrayIndexOutOfBoundsException
    if (startIndex < 0 || startIndex > array.length) {
        throw new IllegalArgumentException("startIndex (" + startIndex + ") must be within the array bounds [0, " + array.length + "]");
    }
    if (endIndex < 0 || endIndex > array.length) {
        throw new IllegalArgumentException("endIndex (" + endIndex + ") must be within the array bounds [0, " + array.length + "]");
    }
    if (startIndex > endIndex) {
        // This case is already handled by noOfItems <= 0, but explicitly checking for clarity
        return EMPTY;
    }

    int noOfItems = (endIndex - startIndex);
    if (noOfItems <= 0) {
        return EMPTY;
    }

    // Improved StringBuilder initial capacity calculation
    // Estimate capacity based on average string length and separator length
    // A reasonable heuristic is to assume an average length (e.g., 16) if actual length is unknown or small,
    // and multiply by the number of items plus separators.
    int estimatedCapacity = 0;
    if (noOfItems > 0) {
        // Try to get the length of the first non-null element, otherwise use a default
        int firstElementLength = 16; // Default average length
        for (int i = startIndex; i < endIndex; i++) {
            if (array[i] != null) {
                firstElementLength = array[i].toString().length();
                break;
            }
        }
        estimatedCapacity = noOfItems * (firstElementLength + separator.length());
        // Ensure minimum capacity to avoid negative or too small values
        if (estimatedCapacity < 0) { // Handle potential overflow if firstElementLength is huge, though unlikely
            estimatedCapacity = Integer.MAX_VALUE;
        } else if (estimatedCapacity == 0 && noOfItems > 0) { // If all elements are empty strings and separator is empty
            estimatedCapacity = 16; // Provide a small default
        }
    }

    StringBuilder buf = new StringBuilder(estimatedCapacity);

    for (int i = startIndex; i < endIndex; i++) {
        if (i > startIndex) {
            buf.append(separator);
        }
        if (array[i] != null) {
            buf.append(array[i]);
        }
    }
    return buf.toString();
}
