import org.apache.commons.lang3.StringUtils; // Assuming this import is available

public class NumberUtils {

    // ... (existing fields and other methods) ...

    /**
     * <p>Checks whether the String a valid Java number.</p>
     *
     * <p>Valid numbers include hexadecimal (0x...), scientific notation (e.g., 1.23e-4),
     * and numbers with type qualifiers (e.g., 123L, 1.23F).</p>
     *
     * <p>This method does not support locale-specific decimal separators or Unicode digits.</p>
     *
     * @param str the String to check
     * @return {@code true} if the string is a valid number, {@code false} otherwise
     */
    public static boolean isNumber(String str) {
        if (StringUtils.isEmpty(str)) {
            return false;
        }

        char[] chars = str.toCharArray();
        int len = chars.length;
        boolean hasExp = false;
        boolean hasDecPoint = false;
        boolean allowSignsInExponent = false;
        boolean foundDigit = false;

        // Deal with any possible sign up front
        int start = 0;
        if (chars[0] == '-' || chars[0] == '+') {
            start = 1;
        }

        // Handle hexadecimal numbers (0x or -0x)
        if (len > start + 1 && chars[start] == '0' && (chars[start + 1] == 'x' || chars[start + 1] == 'X')) {
            int hexStart = start + 2;
            if (hexStart == len) {
                return false; // str == "0x" or "-0x"
            }
            // Checking hex (it can't be anything else)
            for (int i = hexStart; i < len; i++) {
                if (!((chars[i] >= '0' && chars[i] <= '9') ||
                      (chars[i] >= 'a' && chars[i] <= 'f') ||
                      (chars[i] >= 'A' && chars[i] <= 'F'))) {
                    return false;
                }
            }
            return true;
        }

        int i = start;
        // Loop through characters, excluding the last one for type qualifiers
        while (i < len) {
            if (chars[i] >= '0' && chars[i] <= '9') {
                foundDigit = true;
                allowSignsInExponent = false; // A digit invalidates a pending sign for exponent
            } else if (chars[i] == '.') {
                if (hasDecPoint || hasExp) {
                    // Two decimal points or decimal point in exponent part
                    return false;
                }
                hasDecPoint = true;
            } else if (chars[i] == 'e' || chars[i] == 'E') {
                if (hasExp) {
                    // Two 'e' or 'E'
                    return false;
                }
                if (!foundDigit) {
                    // 'e' or 'E' must be preceded by a digit
                    return false;
                }
                hasExp = true;
                allowSignsInExponent = true; // Allow a sign immediately after 'e' or 'E'
                foundDigit = false; // Reset foundDigit to ensure a digit follows the exponent sign
            } else if (chars[i] == '+' || chars[i] == '-') {
                if (!allowSignsInExponent) {
                    // Sign not allowed here (only immediately after 'e'/'E')
                    return false;
                }
                allowSignsInExponent = false; // Only one sign allowed after 'e'/'E'
                foundDigit = false; // Reset foundDigit to ensure a digit follows the exponent sign
            } else {
                // Check for type qualifiers at the end
                if (i == len - 1) { // Only the last character can be a type qualifier
                    if (chars[i] == 'd' || chars[i] == 'D' || chars[i] == 'f' || chars[i] == 'F') {
                        return foundDigit; // Must have found at least one digit
                    }
                    if (chars[i] == 'l' || chars[i] == 'L') {
                        // 'L' is not allowed with an exponent or decimal point
                        return foundDigit && !hasExp && !hasDecPoint;
                    }
                }
                // Any other character or type qualifier not at the end is invalid
                return false;
            }
            i++;
        }

        // Final checks after iterating through all characters
        // If the string ends with a decimal point (e.g., "123."), it's not a valid number.
        if (chars[len - 1] == '.') {
            return false;
        }

        // If the string ends with 'e' or 'E' (allowSignsInExponent would be true), it's not a valid number.
        // Also, ensure at least one digit was found.
        return foundDigit && !allowSignsInExponent;
    }
}
