import java.io.IOException;
import java.io.Writer;

// Assuming this class extends org.apache.commons.lang3.text.translate.CharSequenceTranslator
// and the translate method is an override.

public class NumericEntityUnescaper extends org.apache.commons.lang3.text.translate.CharSequenceTranslator {

    @Override
    public int translate(CharSequence input, int index, Writer out) throws IOException {
        // C1: null input checks
        if (input == null || out == null) {
            // According to CharSequenceTranslator contract, null input should throw NPE.
            // For Writer, it's also a critical dependency.
            throw new NullPointerException("Input CharSequence and Writer must not be null.");
        }

        // C3: boundary/index/length checks for initial characters
        // Need at least 2 characters for "&#"
        if (index < 0 || index >= input.length() - 1) { // -1 because we need to check index + 1
            return 0; // Not enough characters for a potential entity start
        }

        if (input.charAt(index) == '&' && input.charAt(index + 1) == '#') {
            int start = index + 2;
            boolean isHex = false;

            // C3: boundary check for 'x' or 'X'
            if (start >= input.length()) {
                return 0; // Not enough characters after "&#"
            }

            char firstCharAfterHash = input.charAt(start);
            if (firstCharAfterHash == 'x' || firstCharAfterHash == 'X') {
                start++;
                isHex = true;
            }

            // C3: boundary check after 'x'/'X'
            if (start >= input.length()) {
                return 0; // Not enough characters after "&#x"
            }

            int end = start;
            // C3: Robustness for finding the semicolon. Prevent ArrayIndexOutOfBounds.
            // C5: Ensure the characters between start and end are valid digits for the base.
            while (end < input.length() && input.charAt(end) != ';') {
                char c = input.charAt(end);
                if (isHex) {
                    if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) {
                        return 0; // Invalid hex character
                    }
                } else {
                    if (!(c >= '0' && c <= '9')) {
                        return 0; // Invalid decimal character
                    }
                }
                end++;
            }

            // C3: Check if semicolon was found
            if (end == input.length()) {
                return 0; // Semicolon not found, malformed entity
            }

            // C3: Ensure there's at least one digit between start and end
            if (start == end) {
                return 0; // Empty entity, e.g., "&#;" or "&#x;"
            }

            int entityValue;
            try {
                String entityStr = input.subSequence(start, end).toString();
                if (isHex) {
                    entityValue = Integer.parseInt(entityStr, 16);
                } else {
                    entityValue = Integer.parseInt(entityStr, 10);
                }
            } catch (NumberFormatException nfe) {
                // C4: Return 0 for invalid number format
                return 0;
            }

            // C6: Validate entityValue is a valid Unicode code point
            // Although Writer.write(int) handles this, it's good practice to ensure
            // we're not trying to write something completely out of spec.
            if (entityValue < Character.MIN_CODE_POINT || entityValue > Character.MAX_CODE_POINT) {
                return 0; // Not a valid Unicode code point
            }

            out.write(entityValue);
            // C3: Correct calculation of consumed characters
            // 2 for "&#"
            // (end - start) for the numeric part
            // (isHex ? 1 : 0) for 'x'
            // 1 for ';'
            return 2 + (end - start) + (isHex ? 1 : 0) + 1;
        }
        return 0; // Not a numeric entity, consume 0 characters
    }
}
