public static int indexOfAny(String str, String[] searchStrs) {
    // Handle null input for the main string or the array of search strings.
    // Returning INDEX_NOT_FOUND (-1) is a standard practice for "not found" scenarios.
    if (str == null || searchStrs == null) {
        return INDEX_NOT_FOUND;
    }

    // If the array of search strings is empty, no search can be performed.
    // Return INDEX_NOT_FOUND.
    if (searchStrs.length == 0) {
        return INDEX_NOT_FOUND;
    }

    // Initialize 'ret' to the maximum possible integer value.
    // This allows us to easily find the minimum index among all search results.
    // String indices are non-negative, so any valid index will be less than Integer.MAX_VALUE.
    int ret = Integer.MAX_VALUE;

    // Iterate through each search string provided in the array.
    for (String search : searchStrs) {
        // Skip null search strings. This prevents NullPointerExceptions and
        // aligns with the common expectation that null search terms are ignored.
        if (search == null) {
            continue;
        }

        // Find the first occurrence of the current 'search' string within 'str'.
        // String.indexOf() returns -1 if the substring is not found.
        int tmp = str.indexOf(search);

        // If the current search string was not found, move to the next one.
        if (tmp == INDEX_NOT_FOUND) {
            continue;
        }

        // If the current search string was found at an earlier index than
        // any previously found search string, update 'ret'.
        if (tmp < ret) {
            ret = tmp;
        }
    }

    // After checking all search strings, if 'ret' is still Integer.MAX_VALUE,
    // it means none of the search strings were found in 'str'.
    // In this case, return INDEX_NOT_FOUND. Otherwise, return the smallest index found.
    return (ret == Integer.MAX_VALUE) ? INDEX_NOT_FOUND : ret;
}
