import org.apache.commons.lang3.StringUtils; // Assuming this import is available

public class NumberUtils { // Assuming this class structure

    public static boolean isNumber(String str) {
        if (StringUtils.isEmpty(str)) {
            return false;
        }

        // Trim leading/trailing whitespace as is common for number parsing
        str = str.trim();
        if (str.isEmpty()) { // Check again after trimming
            return false;
        }

        char[] chars = str.toCharArray();
        int len = chars.length;
        boolean hasExp = false;
        boolean hasDecPoint = false;
        boolean allowSignsInExponent = false; // Renamed for clarity
        boolean foundDigit = false;

        int start = 0;
        // Deal with any possible sign up front
        if (chars[0] == '-' || chars[0] == '+') {
            start = 1;
        }

        // Handle hexadecimal numbers (0x or 0X)
        if (len > start + 1 && chars[start] == '0' && (chars[start + 1] == 'x' || chars[start + 1] == 'X')) {
            int i = start + 2;
            if (i == len) {
                return false; // str == "0x" or "0X"
            }
            // Checking hex (it can't be anything else)
            for (; i < len; i++) {
                if (!((chars[i] >= '0' && chars[i] <= '9') ||
                      (chars[i] >= 'a' && chars[i] <= 'f') ||
                      (chars[i] >= 'A' && chars[i] <= 'F'))) {
                    return false;
                }
            }
            return true;
        }

        // Main parsing loop
        int i = start;
        while (i < len) {
            if (chars[i] >= '0' && chars[i] <= '9') {
                foundDigit = true;
                allowSignsInExponent = false; // Reset after a digit
            } else if (chars[i] == '.') {
                if (hasDecPoint || hasExp) {
                    // Two decimal points or decimal point in exponent
                    return false;
                }
                hasDecPoint = true;
            } else if (chars[i] == 'e' || chars[i] == 'E') {
                if (hasExp) {
                    // Two E's
                    return false;
                }
                if (!foundDigit) {
                    // Must have a digit before 'e' or 'E'
                    return false;
                }
                hasExp = true;
                allowSignsInExponent = true; // Allow sign for exponent part
                foundDigit = false; // Reset foundDigit, as we need a digit *after* the exponent sign
            } else if (chars[i] == '+' || chars[i] == '-') {
                if (!allowSignsInExponent) {
                    // Sign only allowed at the beginning or after 'e'/'E'
                    return false;
                }
                allowSignsInExponent = false; // Only one sign allowed after 'e'/'E'
                foundDigit = false; // We need a digit after the exponent sign
            } else {
                // Invalid character
                return false;
            }
            i++;
        }

        // After loop, check for type qualifiers or incomplete numbers
        if (!foundDigit) {
            // No digits found at all (e.g., ".", "e", "+", "-")
            return false;
        }

        // Check the last character for type qualifiers
        char lastChar = chars[len - 1];
        if (lastChar == 'd' || lastChar == 'D' || lastChar == 'f' || lastChar == 'F') {
            // Valid float/double qualifier
            return true;
        }
        if (lastChar == 'l' || lastChar == 'L') {
            // Valid long qualifier, but not with an exponent
            return !hasExp;
        }

        // If the last character was 'e' or 'E' and no exponent value followed
        if (hasExp && (lastChar == 'e' || lastChar == 'E' || lastChar == '+' || lastChar == '-')) {
            return false; // Incomplete exponent part (e.g., "123E", "123E+", "123E-")
        }

        // If we reached here, it's a valid number without a specific type qualifier
        // or a valid number with a qualifier already handled.
        // The `foundDigit` check at the beginning of this post-loop section handles cases like "."
        return true;
    }
}
