import org.apache.commons.lang.StringUtils; // Assuming this import is available

public static String getShortClassName(String className) {
    if (StringUtils.isEmpty(className)) { // Use StringUtils.isEmpty for conciseness
        return StringUtils.EMPTY;
    }

    // Handle array encoding (e.g., "[Ljava.lang.String;", "[[I")
    StringBuilder arrayPrefix = new StringBuilder();
    int i = 0;
    while (i < className.length() && className.charAt(i) == '[') {
        arrayPrefix.append("[]");
        i++;
    }
    String strippedClassName = className.substring(i);

    if (strippedClassName.length() == 0) { // Handle cases like "[]" or "[["
        return arrayPrefix.toString();
    }

    // Strip Object type encoding (e.g., "Ljava.lang.String;")
    if (strippedClassName.length() > 0 && strippedClassName.charAt(0) == 'L' && strippedClassName.endsWith(";")) {
        strippedClassName = strippedClassName.substring(1, strippedClassName.length() - 1);
    } else if (strippedClassName.length() == 1) { // Handle primitive type descriptors (e.g., "I", "Z")
        switch (strippedClassName.charAt(0)) {
            case 'B': return "byte" + arrayPrefix.toString();
            case 'C': return "char" + arrayPrefix.toString();
            case 'D': return "double" + arrayPrefix.toString();
            case 'F': return "float" + arrayPrefix.toString();
            case 'I': return "int" + arrayPrefix.toString();
            case 'J': return "long" + arrayPrefix.toString();
            case 'S': return "short" + arrayPrefix.toString();
            case 'Z': return "boolean" + arrayPrefix.toString();
            case 'V': return "void" + arrayPrefix.toString(); // Though void arrays are not possible, for completeness
        }
    }

    int lastDotIdx = strippedClassName.lastIndexOf(PACKAGE_SEPARATOR_CHAR);
    int innerIdx = strippedClassName.indexOf(
            INNER_CLASS_SEPARATOR_CHAR, lastDotIdx == -1 ? 0 : lastDotIdx + 1);
    String out = strippedClassName.substring(lastDotIdx + 1);
    if (innerIdx != -1) {
