public static String getPackageName(String className) {
    if (className == null || className.isEmpty()) {
        return StringUtils.EMPTY;
    }

    // Handle array encoding: e.g., "[Ljava.lang.String;" -> "java.lang.String"
    // Handle object type encoding: e.g., "Ljava.lang.Object;" -> "java.lang.Object"
    // This also implicitly handles primitive array types like "[I" (int[])
    if (className.charAt(0) == '[') {
        int firstSemiColon = className.indexOf(';');
        if (firstSemiColon != -1 && className.charAt(firstSemiColon - 1) == 'L') {
            // It's an object array, e.g., "[Ljava.lang.String;"
            className = className.substring(2, firstSemiColon); // Remove "[L" and ";"
        } else {
            // It's a primitive array, e.g., "[I" for int[]. Primitive arrays have no package.
            return StringUtils.EMPTY;
        }
    } else if (className.charAt(0) == 'L' && className.endsWith(";")) {
        // It's an object type encoding, e.g., "Ljava.lang.Object;"
        className = className.substring(1, className.length() - 1); // Remove "L" and ";"
    }

    int i = className.lastIndexOf(PACKAGE_SEPARATOR_CHAR);
    if (i == -1) {
        return StringUtils.EMPTY;
    }
    return className.substring(0, i);
}
