import org.apache.commons.lang.StringUtils;

public class WordUtils {

    // Other methods would be here as provided in the original context

    /**
     * Abbreviates a String to a certain length, preferring to cut at a word boundary.
     *
     * This method truncates the given string `str` to a maximum length specified by `upper`.
     * It attempts to find the last space character within the range from `lower` to `upper`
     * (inclusive of `lower`, exclusive of `upper`) and truncates the string at that space.
     * If no space is found within this range, or if `upper` is less than `lower`,
     * it truncates the string at `upper`.
     *
     * If the original string is actually abbreviated (i.e., its length is greater than
     * the resulting abbreviated string's length), the `appendToEnd` string will be appended.
     *
     * @param str The string to abbreviate, may be null.
     * @param lower The minimum length of the abbreviated string. If the string is shorter
     *              than this, it will not be abbreviated unless `upper` forces it.
     *              Must be non-negative. If negative, it will be treated as 0.
     * @param upper The maximum length of the abbreviated string. If the string is longer
     *              than this, it will be abbreviated. If -1 or greater than the string's
     *              length, it will be treated as the string's length.
     * @param appendToEnd The string to append to the end of the abbreviated string if
     *                    abbreviation occurs. May be null, in which case an empty string is used.
     * @return The abbreviated string, or null if the input string was null.
     */
    public static String abbreviate(String str, int lower, int upper, String appendToEnd) {
        // initial parameter checks
        if (str == null) {
            return null;
        }
        if (str.length() == 0) {
            return StringUtils.EMPTY;
        }

        // Normalize lower and upper bounds
        final int strLen = str.length();
        lower = Math.max(0, lower); // Ensure lower is not negative
        upper = (upper == -1 || upper > strLen) ? strLen : upper; // Normalize upper

        // Ensure upper is not less than lower after normalization
        upper = Math.max(lower, upper);

        // If the string is already shorter than or equal to the upper limit, no abbreviation needed.
        if (strLen <= upper) {
            return str;
        }

        // Find the last space before or at the upper limit, but not before lower
        // We search from upper-1 down to lower to find the last possible word boundary.
        int lastSpaceIndex = -1;
        for (int i = Math.min(upper - 1, strLen - 1); i >= lower; i--) {
            if (str.charAt(i) == ' ') {
                lastSpaceIndex = i;
                break;
            }
        }

        StringBuilder result = new StringBuilder();
        String suffix = StringUtils.defaultString(appendToEnd);

        if (lastSpaceIndex != -1) {
            // A space was found within the desired range [lower, upper-1]
            result.append(str.substring(0, lastSpaceIndex));
            result.append(suffix);
        } else {
            // No space found within the desired range, or lower was too high.
            // Truncate at upper.
            result.append(str.substring(0, upper));
            result.append(suffix);
        }

        return result.toString();
    }
}
