package org.apache.commons.lang3.text.translate;

import java.io.IOException;
import java.io.Writer;
import java.util.HashMap;

// Assuming LookupTranslator class structure as provided
public class LookupTranslator extends CharSequenceTranslator {

    private final HashMap<CharSequence, CharSequence> lookupMap;
    private final int shortest;
    private final int longest;

    // Constructor as provided
    public LookupTranslator(final CharSequence[]... lookup) {
        lookupMap = new HashMap<>();
        int currentShortest = Integer.MAX_VALUE;
        int currentLongest = 0;

        if (lookup != null) {
            for (final CharSequence[] pair : lookup) {
                if (pair != null && pair.length == 2) {
                    final CharSequence key = pair[0];
                    final CharSequence value = pair[1];
                    if (key != null && value != null) {
                        lookupMap.put(key, value);
                        final int len = key.length();
                        if (len < currentShortest) {
                            currentShortest = len;
                        }
                        if (len > currentLongest) {
                            currentLongest = len;
                        }
                    }
                }
            }
        }
        this.shortest = currentShortest == Integer.MAX_VALUE ? 0 : currentShortest;
        this.longest = currentLongest;
    }

    @Override
    public int translate(final CharSequence input, final int index, final Writer out) throws IOException {
        // Robustness Omission: C1 null input, C4 error contract
        if (input == null) {
            throw new IllegalArgumentException("Input CharSequence cannot be null.");
        }
        if (out == null) {
            throw new IllegalArgumentException("Writer cannot be null.");
        }

        // Robustness Omission: C3 boundary/index/length, C4 error contract
        if (index < 0 || index > input.length()) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Input length: " + input.length());
        }
        // If index is at the end of the input, no characters can be translated.
        if (index == input.length()) {
            return 0;
        }

        // Original logic for max length calculation
        int max = longest;
        if (index + longest > input.length()) {
            max = input.length() - index;
        }

        // Descend so as to get a greedy algorithm (longest match first)
        for (int i = max; i >= shortest; i--) {
            // Ensure that the subsequence length 'i' is valid for the remaining input
            if (index + i > input.length()) {
                // This condition should ideally be caught by the 'max' calculation,
                // but as a defensive check, it ensures 'subSequence' doesn't fail.
                // However, given 'max' is correctly calculated, this branch is unlikely to be hit
                // unless 'shortest' is somehow greater than 'max' initially, which is handled by the loop condition.
                continue;
            }

            final CharSequence subSeq = input.subSequence(index, index + i);
            final CharSequence result = lookupMap.get(subSeq);
            if (result != null) {
                out.write(result.toString());
                return i; // Return the number of characters consumed from the input
            }
        }
        return 0; // No match found
    }
}
