import java.util.Locale;

public class LocaleUtils {

    // ... (existing fields and other methods would be here)

    /**
     * Converts a string representation of a locale into a {@code Locale} object.
     * This method supports the following string formats:
     * <ul>
     *     <li>Language: "en"</li>
     *     <li>Language and Country: "en_US"</li>
     *     <li>Language, Country, and Variant: "en_US_VAR"</li>
     *     <li>Language and Variant (with empty country): "en__VAR"</li>
     * </ul>
     * The language code must be two lowercase letters.
     * The country code must be two uppercase letters.
     * The variant can be any string.
     *
     * @param str The string to convert, may be null.
     * @return The corresponding {@code Locale} object, or {@code null} if the input string is {@code null}.
     * @throws IllegalArgumentException if the string is not in a valid locale format.
     */
    public static Locale toLocale(final String str) {
        if (str == null) {
            return null;
        }
        final int len = str.length();

        if (len < 2) {
            throw new IllegalArgumentException("Invalid locale format: " + str);
        }

        final char ch0 = str.charAt(0);
        final char ch1 = str.charAt(1);

        // Language code must be two lowercase letters
        if (!Character.isLowerCase(ch0) || !Character.isLowerCase(ch1)) {
            throw new IllegalArgumentException("Invalid locale format: " + str);
        }

        // Handle language only (e.g., "en")
        if (len == 2) {
            return new Locale(str);
        }

        // All other formats must have an underscore at index 2
        if (str.charAt(2) != '_') {
            throw new IllegalArgumentException("Invalid locale format: " + str);
        }

        // Handle language and variant with empty country (e.g., "en__VAR")
        // This is a specific case where the country code is empty, indicated by two underscores.
        if (len >= 4 && str.charAt(3) == '_') { // Check len >= 4 to safely access charAt(3)
            // Format: language__variant
            // Example: "en__VAR" -> Locale("en", "", "VAR")
            return new Locale(str.substring(0, 2), "", str.substring(4));
        }

        // Handle language and country (e.g., "en_US") or language, country, and variant (e.g., "en_US_VAR")
        if (len < 5) {
            // If length is 3 or 4, and we've passed the language__variant check,
            // it means it's "ll_C" or "ll_CC" but not "ll_CC_V".
            // For "ll_C", it's invalid as country must be 2 chars.
            // For "ll_CC", it's valid.
            throw new IllegalArgumentException("Invalid locale format: " + str);
        }

        final char ch3 = str.charAt(3);
        final char ch4 = str.charAt(4);

        // Country code must be two uppercase letters
        if (!Character.isUpperCase(ch3) || !Character.isUpperCase(ch4)) {
            throw new IllegalArgumentException("Invalid locale format: " + str);
        }

        // Handle language and country only (e.g., "en_US")
        if (len == 5) {
            return new Locale(str.substring(0, 2), str.substring(3, 5));
        }

        // Handle language, country, and variant (e.g., "en_US_VAR")
        // Must have an underscore at index 5 for variant
        if (str.charAt(5) != '_') {
            throw new IllegalArgumentException("Invalid locale format: " + str);
        }

        // Format: language_country_variant
        // Example: "en_US_VAR" -> Locale("en", "US", "VAR")
        return new Locale(str.substring(0, 2), str.substring(3, 5), str.substring(6));
    }
}
